const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = process.env.QDRANT_API_KEY || '';
const OLLAMA_URL = 'http://host.docker.internal:11434';

async function qdrantScroll(collection, filter, limit=100) {
  const body = {limit, with_payload: true, with_vector: false};
  if (filter) body.filter = filter;
  const r = await fetch(`${QDRANT_URL}/collections/${collection}/points/scroll`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify(body)
  });
  const d = await r.json();
  return d.result?.points || [];
}

async function qdrantStore(collection, id, vector, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points`, {
    method: 'PUT', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({points: [{id, vector, payload}]})
  });
}

async function qdrantUpdate(collection, ids, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points/payload`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({payload, points: ids})
  });
}

async function embed(text) {
  const r = await fetch(`${OLLAMA_URL}/api/embed`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({model: 'nomic-embed-text', input: text})
  });
  const d = await r.json();
  return d.embeddings?.[0] || null;
}

function uuid() { return crypto.randomUUID(); }

// Phase 1: Replay — scan recent episodes
const episodes = await qdrantScroll('episodes', null, 50);
const now = Date.now();
const recentEpisodes = episodes.filter(e => {
  const created = new Date(e.payload?.created_at || 0).getTime();
  return (now - created) < 48 * 60 * 60 * 1000; // last 48h
});

// Phase 2: Tier transfer
const hotMemories = await qdrantScroll('memories_hot', null, 100);
const transferredToWarm = [];
const pruned = [];

for (const m of hotMemories) {
  const created = new Date(m.payload?.created_at || 0).getTime();
  const ageHours = (now - created) / (60 * 60 * 1000);
  const recallCount = m.payload?.recall_count || 0;

  if (ageHours >= 24 && recallCount >= 2) {
    // hot -> warm
    const vec = await embed(m.payload?.content || '');
    if (vec) {
      await qdrantStore('memories_warm', m.id, vec, {...m.payload, tier: 'warm', promoted_at: new Date().toISOString()});
      transferredToWarm.push(m.id);
    }
  } else if (ageHours >= 48 && recallCount === 0) {
    // hot -> pruned (never recalled)
    const vec = await embed(m.payload?.content || '');
    if (vec) {
      await qdrantStore('memories_cold', m.id, vec, {...m.payload, tier: 'cold', pruned_at: new Date().toISOString(), prune_reason: 'never_recalled_48h'});
      pruned.push(m.id);
    }
  }
}

// Phase 3: Log consolidation cycle
const cycleId = uuid();
const cycleVec = await embed('consolidation cycle ' + new Date().toISOString());
if (cycleVec) {
  await qdrantStore('consolidation_cycles', cycleId, cycleVec, {
    cycle_id: cycleId, timestamp: new Date().toISOString(),
    episodes_reviewed: recentEpisodes.length,
    transferred_to_warm: transferredToWarm.length,
    pruned: pruned.length,
    status: 'completed'
  });
}

return [{json: {episodes: recentEpisodes.length, transferred: transferredToWarm.length, pruned: pruned.length}}];
